mapper.sql:
	left join FIN_CASH_INFO finCashInfoSale
	 		on FIN_PRODUCT.FINPROD_ID = finCashInfoSale.FINPROD_ID
		   and finCashInfoSale.FINPROD_TYPE = #{cashTypeFinProd}
		   and finCashInfoSale.CASH_TYPE_1 = #{cashFirstTypeFee}
		   and finCashInfoSale.CASH_TYPE_2 = #{cashSecondTypeSale}
		   and finCashInfoSale.BRANCH = #{branch}
	left join (
			select FIN_CASH_CALC_RULE.CASH_ID, FIN_CASH_CALC_RULE.BASIS, FIN_CASH_CALC_RULE.YIELD YIELD
			  from FIN_CASH_CALC_RULE
			inner join (select CASH_ID, max(EFF_DATE) EFF_DATE
						from FIN_CASH_CALC_RULE
				   where EFF_DATE <= #{platDate}
				   group by CASH_ID) finCashCalcRule
					on FIN_CASH_CALC_RULE.EFF_DATE = finCashCalcRule.EFF_DATE
		   		   and FIN_CASH_CALC_RULE.CASH_ID = finCashCalcRule.CASH_ID
   		   ) tempSale
   	on finCashInfoSale.CASH_ID = tempSale.CASH_ID

	left join FIN_CASH_INFO finCashInfoOSale
	 		on FIN_PRODUCT.FINPROD_ID = finCashInfoOSale.FINPROD_ID
		   and finCashInfoOSale.FINPROD_TYPE = #{cashTypeFinProd}
		   and finCashInfoOSale.CASH_TYPE_1 = #{cashFirstTypeFee}
		   and finCashInfoOSale.CASH_TYPE_2 = #{cashSecondTypeOSale}
		   and finCashInfoOSale.BRANCH = #{branch}
	left join (
			select FIN_CASH_CALC_RULE.CASH_ID, FIN_CASH_CALC_RULE.BASIS, FIN_CASH_CALC_RULE.YIELD YIELD
			  from FIN_CASH_CALC_RULE
			inner join (select CASH_ID, max(EFF_DATE) EFF_DATE
						from FIN_CASH_CALC_RULE
				   where EFF_DATE <= #{platDate}
				   group by CASH_ID) finCashCalcRule
					on FIN_CASH_CALC_RULE.EFF_DATE = finCashCalcRule.EFF_DATE
		   		   and FIN_CASH_CALC_RULE.CASH_ID = finCashCalcRule.CASH_ID
   		   ) tempOSale
   	on finCashInfoOSale.CASH_ID = tempOSale.CASH_ID

	left join FIN_CASH_INFO finCashInfoInt
	 		on FIN_PRODUCT.FINPROD_ID = finCashInfoInt.FINPROD_ID
		   and finCashInfoInt.FINPROD_TYPE = #{cashTypeFinProd}
		   and finCashInfoInt.CASH_TYPE_1 = #{cashFirstTypeInt}
		   and finCashInfoInt.CASH_TYPE_2 = #{cashSecondTypeInt}
		   and finCashInfoInt.BRANCH = #{branch}
	 left join FIN_RATE_INFO
	 		on finCashInfoInt.CASH_ID = FIN_RATE_INFO.CASH_ID
	 		and FIN_RATE_INFO.EFF_DATE = TO_DATE('${startDate}', 'yyyy-MM-dd')
	 left join (

		select FIN_CASH_CALC_RULE.CASH_ID, FIN_CASH_CALC_RULE.YIELD YIELD
		  from FIN_CASH_CALC_RULE
		inner join (select FIN_CASH_CALC_RULE.CASH_ID, max(FIN_CASH_CALC_RULE.EFF_DATE) EFF_DATE
					from FIN_CASH_CALC_RULE, FIN_PRODUCT_ADD
			   where FIN_CASH_CALC_RULE.EFF_DATE <= #{platDate}
			     and FIN_CASH_CALC_RULE.FINPROD_ID = FIN_PRODUCT_ADD.FINPROD_ID
			     and FIN_PRODUCT_ADD.IS_LAY = #{yesNoNo}
			   group by FIN_CASH_CALC_RULE.CASH_ID) finCashCalcRule
				on FIN_CASH_CALC_RULE.EFF_DATE = finCashCalcRule.EFF_DATE
	   		   and FIN_CASH_CALC_RULE.CASH_ID = finCashCalcRule.CASH_ID

	   	union all
	   	select FIN_RATE_INFO.CASH_ID, FIN_RATE_INFO.RATE YIELD
		  from FIN_RATE_INFO, FIN_PRODUCT_ADD
		 where FIN_RATE_INFO.FINPROD_ID = FIN_PRODUCT_ADD.FINPROD_ID
	       and FIN_PRODUCT_ADD.IS_LAY = #{yes}
       ) tempInt on finCashInfoInt.CASH_ID = tempInt.CASH_ID

mapper.select:
select '${branch}' branch, '${startDate}' startDate, '${endDate}' endDate, INTERF_PROD_LADDER_DETAIL.STARTCUSTOMERLEVEL customLevel, INTERF_PROD_LADDER_DETAIL.STARTAMOUNT amtMin, INTERF_PROD_LADDER_DETAIL.ENDAMOUNT amtMax, INTERF_PROD_LADDER_DETAIL.ENDDAYNUM termMax, INTERF_PROD_LADDER_DETAIL.STARTDAYNUM termMin, NVL(INTERF_PROD_LADDER_DETAIL.DRAWAMOUNT, INTERF_PROD_INFO.TOTALCURRENTAMOUNT) tdyPrinAmt, NVL(INTERF_PROD_LADDER_DETAIL.TOTALPROFITAMOUNT, INTERF_PROD_INFO.TOTALPAYABLEINTEREST) intAmt, NVL(INTERF_PROD_LADDER_DETAIL.REFADDRATE, tempInt.YIELD) yield, FIN_RATE_INFO.BASIS basis, PRD_LAYER_PARAM.FINPROD_ID finprodId from INTERF_PROD_INFO left join INTERF_PROD_LADDER_DETAIL on INTERF_PROD_INFO.PRODID = INTERF_PROD_LADDER_DETAIL.PRODID and INTERF_PROD_LADDER_DETAIL.CDATE = INTERF_PROD_LADDER_DETAIL.CDATE left join FIN_PRODUCT on FIN_PRODUCT.FINPROD_MARKET_ID = INTERF_PROD_INFO.PRODID left join PRD_LAYER_PARAM
on decode(INTERF_PROD_LADDER_DETAIL.STARTCUSTOMERLEVEL, null, 'default', INTERF_PROD_LADDER_DETAIL.STARTCUSTOMERLEVEL) = decode(PRD_LAYER_PARAM.CUSTOM_LEVEL, 'default', PRD_LAYER_PARAM.CUSTOM_LEVEL) and decode(INTERF_PROD_LADDER_DETAIL.STARTAMOUNT, null, 'default', INTERF_PROD_LADDER_DETAIL.STARTAMOUNT) = decode(PRD_LAYER_PARAM.AMT_MIN, null, 'default', PRD_LAYER_PARAM.AMT_MIN) and decode(INTERF_PROD_LADDER_DETAIL.ENDAMOUNT, null, 'default', INTERF_PROD_LADDER_DETAIL.ENDAMOUNT) = decode(PRD_LAYER_PARAM.AMT_MAX, null, 'default', PRD_LAYER_PARAM.AMT_MAX) and decode(INTERF_PROD_LADDER_DETAIL.STARTDAYNUM, null, 'default', INTERF_PROD_LADDER_DETAIL.STARTDAYNUM) = decode(PRD_LAYER_PARAM.TERM_MIN, null, 'default', PRD_LAYER_PARAM.TERM_MIN) and decode(INTERF_PROD_LADDER_DETAIL.ENDDAYNUM, null, 'default', INTERF_PROD_LADDER_DETAIL.ENDDAYNUM) = decode(PRD_LAYER_PARAM.TERM_MAX, null, 'default', PRD_LAYER_PARAM.TERM_MAX) and INTERF_PROD_LADDER_DETAIL.CDATE = to_char(PRD_LAYER_PARAM.VDATE , 'yyyyMMdd') and PRD_LAYER_PARAM.P_FINPROD_ID = FIN_PRODUCT.FINPROD_ID left join FIN_CASH_INFO finCashInfoInt on FIN_PRODUCT.FINPROD_ID = finCashInfoInt.FINPROD_ID and finCashInfoInt.FINPROD_TYPE = #{cashTypeFinProd} and finCashInfoInt.CASH_TYPE_1 = #{cashFirstTypeInt} and finCashInfoInt.CASH_TYPE_2 = #{cashSecondTypeInt} and finCashInfoInt.BRANCH = #{branch} left join FIN_RATE_INFO on finCashInfoInt.CASH_ID = FIN_RATE_INFO.CASH_ID and FIN_RATE_INFO.EFF_DATE = to_date(INTERF_PROD_INFO.STARTDATE, 'yyyy-MM-dd') where FIN_PRODUCT.FINPROD_ID = #{finprodId} and INTERF_PROD_INFO.STARTDATE = #{branch} and INTERF_PROD_INFO.PINAN_BUSINESS_TYPE = #{paBussTypeM} union all
select '${branch}' branch, '${startDate}' startDate, '${endDate}' endDate, PRD_LAYER_PARAM.CUSTOM_LEVEL customLevel, PRD_LAYER_PARAM.AMT_MIN amtMin, PRD_LAYER_PARAM.AMT_MAX amtMax, PRD_LAYER_PARAM.TERM_MAX termMax, PRD_LAYER_PARAM.TERM_MIN termMin, positionTemp.AMOUNT tdyPrinAmt, NULL intAmt, NVL(PRD_LAYER_PARAM.YIELD, tempInt.YIELD) yield, FIN_RATE_INFO.BASIS basis, PRD_LAYER_PARAM.FINPROD_ID finprodId from FIN_PRODUCT left join PRD_LAYER_PARAM on FIN_PRODUCT.FINPROD_ID = PRD_LAYER_PARAM.P_FINPROD_ID left join () positionTemp on FIN_PRODUCT.FINPROD_ID = positionTemp.FINPROD_ID and positionTemp.CDATE = to_date(#{endDate}, 'yyyy-MM-dd') - 1 and positionTemp.BRANCH = #{branch}
and not exists (select 1 from INTERF_PROD_INFO, FIN_PRODUCT where FIN_PRODUCT.FINPROD_MARKET_ID = INTERF_PROD_INFO.PRODID and FIN_PRODUCT.FINPROD_ID = #{finprodId} and INTERF_PROD_INFO.STARTDATE = #{branch} ) where FIN_PRODUCT.FINPROD_ID = #{finprodId}

mapper.sql:

select PTL_SEC_POSITION.FINPROD_ID, PTL_SEC_POSITION.BRANCH, PTL_SEC_POSITION.CDATE, sum(NVL(PTL_SEC_POSITION.AMOUNT, 0)) AMOUNT
			from PTL_SEC_POSITION
			where PTL_SEC_POSITION.HODING_TYPE = #{hodingType}

				and PTL_SEC_POSITION.BRANCH = #{branch}


				and PTL_SEC_POSITION.FINPROD_ID = #{finprodId}


				and PTL_SEC_POSITION.FINPROD_ID in 

					#{item}


			group by PTL_SEC_POSITION.FINPROD_ID, PTL_SEC_POSITION.BRANCH, PTL_SEC_POSITION.CDATE
union all

select PTL_SEC_POSITION.P_FINPROD_ID FINPROD_ID, PTL_SEC_POSITION.BRANCH, PTL_SEC_POSITION.CDATE, sum(NVL(PTL_SEC_POSITION.AMOUNT, 0)) AMOUNT
			from PTL_SEC_POSITION
			where PTL_SEC_POSITION.HODING_TYPE = #{hodingType}

				and PTL_SEC_POSITION.BRANCH = #{branch}


				and PTL_SEC_POSITION.P_FINPROD_ID = #{finprodId}


				and PTL_SEC_POSITION.FINPROD_ID in 

					#{item}


			group by PTL_SEC_POSITION.P_FINPROD_ID, PTL_SEC_POSITION.BRANCH, PTL_SEC_POSITION.CDATE

mapper.select:
    	select  MST_FEEINFO.FEE_NAME feeName,
    			MST_FEEINFO.FEE_TYPE feeType,
    			NVL2(TRD_PRODUCT_DEAL.MDATE, 
    						(CASE WHEN TO_DATE('${startDate}', 'yyyy-MM-dd') > TRD_PRODUCT_DEAL.MDATE
    							THEN '${startDate}' ELSE TO_CHAR(TRD_PRODUCT_DEAL.MDATE, 'yyyy-MM-dd')
    							END), '${startDate}'
    				) startDate,
    			'${endDate}' endDate,
    			positionTemp.AMOUNT prinamt,
				feeRateTemp.BASIS basis,
				feeRateTemp.YIELD * 100 feeRate
    	from FIN_PRODUCT
    	LEFT JOIN (select TRD_PRODUCT_DEAL.FINPROD_ID, max(TRD_PRODUCT_DEAL.MDATE) MDATE
	    			from TRD_PRODUCT_DEAL
	    			where TRD_PRODUCT_DEAL.BRANCH = #{branch}
	    			AND TRD_PRODUCT_DEAL.BUSI_TYPE = #{busiType}
	    			AND TRD_PRODUCT_DEAL.PS = #{ps}
	    			AND TRD_PRODUCT_DEAL.IS_CLEAN = #{yesFlag}
	    			AND TRD_PRODUCT_DEAL.IS_CANCEL != #{yesFlag}
	    			AND TRD_PRODUCT_DEAL.TRADE_STATUS = #{tradeStatusInit}
	    			group by TRD_PRODUCT_DEAL.FINPROD_ID
	    		) TRD_PRODUCT_DEAL
    		ON FIN_PRODUCT.FINPROD_ID = TRD_PRODUCT_DEAL.FINPROD_ID

    	INNER JOIN FIN_CASH_INFO finCashInfoFee
    			ON finCashInfoFee.FINPROD_ID = FIN_PRODUCT.FINPROD_ID
    			AND finCashInfoFee.BRANCH = #{branch}
    			AND finCashInfoFee.CASH_TYPE_1 = #{cashType1}
    			AND finCashInfoFee.CASH_TYPE_2 != #{cashType2}
  		LEFT JOIN (  select FIN_CASH_CALC_RULE.CASH_ID, FIN_CASH_CALC_RULE.BASIS, FIN_CASH_CALC_RULE.YIELD
						  from FIN_CASH_CALC_RULE
	 				inner join (select CASH_ID, max(EFF_DATE) EFF_DATE
	 							from FIN_CASH_CALC_RULE
							   where EFF_DATE <= #{platDate}
							   	 AND BRANCH = #{branch}
							   group by CASH_ID) finCashCalcRule
	 						on FIN_CASH_CALC_RULE.EFF_DATE = finCashCalcRule.EFF_DATE
	 			   		   and FIN_CASH_CALC_RULE.CASH_ID = finCashCalcRule.CASH_ID) feeRateTemp
	 			ON finCashInfoFee.CASH_ID = feeRateTemp.CASH_ID

    	LEFT JOIN MST_FEEINFO ON finCashInfoFee.FEE_ID = MST_FEEINFO.FEE_ID

		LEFT JOIN () positionTemp
				on FIN_PRODUCT.FINPROD_ID = positionTemp.FINPROD_ID
				and #{branch} = positionTemp.BRANCH
				and TO_DATE('${endDate}', 'yyyy-MM-dd') - 1 = positionTemp.CDATE

		where FIN_PRODUCT.FINPROD_ID = #{finprodId} OR FIN_PRODUCT.P_FINPROD_ID = #{finprodId}

select FIN_PRODUCT.FINPROD_ID finprodId, FIN_PRODUCT.FINPROD_MARKET_ID finprodMarketId, FIN_PRODUCT_ADD.TMPL_ID tmplId, FIN_PRODUCT.FINPROD_NAME finprodName, FIN_PRODUCT.FINPROD_ABBR finprodAbbr,
FIN_PRODUCT_ADD.PORTFOLIO_ID ptlId, FIN_PRODUCT_ADD.DEAL_MODE dealMode, FIN_PRODUCT.PROFIT_TYPE profitType, FIN_PRODUCT.OPERATION_TYPE operationType,
FIN_RATE_INFO.INT_TYPE calcType, FIN_PRODUCT_ADD.IS_CYCLE isCycle, FIN_PRODUCT_ADD.IS_LAY isLay, FIN_PRODUCT_ADD.LAY_TYPE layType, FIN_PRODUCT_ADD.PROFIT_FLAG profitFlag, FIN_PRODUCT.ENTRUST_TYPE entrustType, FIN_PRODUCT.ENTRUSTER entruster, FIN_RATE_INFO.RATE * 100 yield, PRD_SALE_PARAM.FIRST_SALE_VDATE firstSaleVdate, PRD_SALE_PARAM.FIRST_SALE_MDATE firstSaleMdate, FIN_PRODUCT.VDATE vdate, FIN_PRODUCT.MDATE mdate, FIN_PRODUCT_ADD.CLOSE_DAYS closeDays, FIN_PRODUCT.TERM_DAYS termDays, FIN_PRODUCT.CALENDAR_ID calendarId, FIN_RATE_INFO.BASIS basis, FIN_PRODUCT.CCY ccy, FIN_PRODUCT_ADD.SALE_DEPARTMENT saleDepartment, FIN_PRODUCT_ADD.PUR_SPEED purSpeed, FIN_PRODUCT.ISSUE_TYPE issueType, FIN_PRODUCT_ADD.INVEST_NATURE investNature, FIN_PRODUCT_ADD.SALE_MODE saleMode,
FIN_PRODUCT_TYPE.TYPE_6 prodSeries, FIN_PRODUCT_TYPE.TYPE_7 prodClass, FIN_PRODUCT_TYPE.TYPE_8 prodFeature, FIN_PRODUCT.TRUSTEE_ID trusteeId, PA_FIN_PRODUCT.exclusive_Prod exclusiveProd,
FIN_PRODUCT_ADD.prod_Manager prodManager, PA_FIN_PRODUCT.sale_Type saleType, PA_FIN_PRODUCT.same_Org sameOrg,
FIN_PRODUCT_ADD.investment_Cycle investmentCycle, PRD_SALE_PARAM.consignment_Flag consignmentFlag, PRD_SALE_PARAM.beforeEnd_Flag beforeEndFlag, PRD_SALE_PARAM.red_Flag redFlag, PRD_SALE_PARAM.defaultRed_Flag defaultRedFlag, PRD_SALE_PARAM.beforeEstablish_Flag beforeEstablishFlag, PRD_SALE_PARAM.continue_Flag continueFlag, FIN_CASH_PAY_RULE.pay_Type payType, FIN_PRODUCT.is_Sus isSus, FIN_PRODUCT_ADD.prod_Regist_Code prodRegistCode, FIN_PRODUCT.LIQUIDATION_DATE liquidationDate from FIN_PRODUCT left join FIN_PRODUCT_ADD on FIN_PRODUCT.FINPROD_ID = FIN_PRODUCT_ADD.FINPROD_ID left join PA_FIN_PRODUCT on FIN_PRODUCT.FINPROD_ID = PA_FIN_PRODUCT.FINPROD_ID left join FIN_PRODUCT_TYPE on FIN_PRODUCT_TYPE.FINPROD_ID = FIN_PRODUCT.FINPROD_ID left join FIN_CASH_INFO on FIN_PRODUCT.FINPROD_ID = FIN_CASH_INFO.FINPROD_ID and FIN_CASH_INFO.CASH_TYPE_1 = #{cashType1} and FIN_CASH_INFO.CASH_TYPE_2 = #{cashType2}
and FIN_CASH_INFO.BRANCH = #{branch}
left join FIN_RATE_INFO on FIN_CASH_INFO.CASH_ID = FIN_RATE_INFO.CASH_ID and (FIN_PRODUCT.VDATE IS NULL OR FIN_RATE_INFO.EFF_DATE = FIN_PRODUCT.VDATE) left join PRD_SALE_PARAM on FIN_PRODUCT.FINPROD_ID = PRD_SALE_PARAM.FINPROD_ID left join FIN_CASH_PAY_RULE on FIN_CASH_INFO.CASH_ID = FIN_CASH_PAY_RULE.CASH_ID and ROWNUM=1 where FIN_PRODUCT.FINPROD_TYPE2 = #{finprodType2}
and FIN_PRODUCT.mdate = to_date(#{mdate}, 'yyyy-MM-dd')
and FIN_PRODUCT.FINPROD_MARKET_ID = #{finprodMarketId}

       select count(1) from TRD_FIN_PRODUCT_DEAL_TOTAL
			  where FINPROD_ID  = #{finprodId} 
			  	and PS = #{ps}
			  	and TRADE_STATUS = #{tradeStatus01}
			  	and IS_CANCEL = #{isCancelN}
